package main
import("context";"encoding/json";"os";"github.com/alekpopovic/orch/internal/controlplane";"github.com/alekpopovic/orch/internal/events";"github.com/alekpopovic/orch/pkg/types")
func main(){ctx:=context.Background();s:=controlplane.NewMemoryService();n,err:=s.RegisterNode(ctx,controlplane.NodeRegistration{Name:"atlas-event-fixture",AdvertiseAddress:"127.0.0.1:18091",Capacity:types.Resources{CPU:1000,Memory:512<<20},Allocatable:types.Resources{CPU:1000,Memory:512<<20}});if err!=nil{panic(err)};svc,err:=s.CreateService(ctx,types.ServiceSpec{Name:"atlas-api",Image:"nginx:1.27-alpine",Replicas:1,RestartPolicy:types.RestartPolicy{Condition:types.RestartNever}});if err!=nil{panic(err)};tasks,err:=s.ListAssignedTasks(ctx,n.Node.ID);if err!=nil||len(tasks)!=1{panic("missing fixture assignment")};for _,status:=range []types.TaskStatus{types.TaskPulling,types.TaskCreated,types.TaskRunning,types.TaskHealthy}{_,err=s.ReportTaskStatus(ctx,controlplane.TaskStatusReport{TaskID:tasks[0].Task.ID,NodeID:n.Node.ID,Status:status,ContainerID:"fixture-container-no-docker"});if err!=nil{panic(err)}};if _,err=s.ScaleService(ctx,svc.ID,2);err!=nil{panic(err)};timeline,err:=s.ListEvents(ctx,events.Filter{Limit:100});if err!=nil{panic(err)};seen:=map[string]bool{};for _,e:=range timeline{seen[e.Type]=true};if !seen["service.created"]||!seen["service.scaled"]||!seen["task.status"]{panic("missing actual events")};json.NewEncoder(os.Stdout).Encode(map[string]any{"scope":"actual MemoryService event generation from injected task reports; no HTTP/Docker/container execution","service_id":svc.ID,"task_id":tasks[0].Task.ID,"events":timeline})}
